__NUXT_JSONP__("/desarrollo-sostenible/noticias/asi_seria_mi_ciudad_ideal_en_el_mexico_del_futuro", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D){return {data:[{post:{slug:"asi_seria_mi_ciudad_ideal_en_el_mexico_del_futuro",title:"Así sería mi ciudad ideal en el México del futuro",date:"2024-11-21T16:54:57.935Z",img:"https:\u002F\u002Fucarecdn.com\u002Fed7246ea-9aa9-4e18-b75a-eb40a179ecd3\u002F","img-alt":"Liliana Alvarado",autor:"Alejandro Santos Cid, El País",link:"https:\u002F\u002Felpais.com\u002Fmexico\u002F2024-11-17\u002Fasi-seria-mi-ciudad-ideal-en-el-mexico-del-futuro.html",category:"desarrollo-sostenible",extracto:"Seis mexicanos —una ambientalista, un periodista de derechos humanos, una académica especializada en violencia, un curador de arte, una experta en políticas públicas y un biólogo marino— idean la ciudad perfecta del mañana",toc:[{id:q,depth:f,text:r},{id:s,depth:f,text:t},{id:u,depth:f,text:v},{id:w,depth:f,text:x},{id:y,depth:f,text:z},{id:A,depth:f,text:B}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Algunos apuntes desordenados para un México mejor: las personas, la participación ciudadana, vecinos que vigilen, cuiden y se apropien de sus ciudades ocupando los huecos que el Estado abandona;"},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Famerica-futura\u002F2023-04-14\u002Ftres-actos-siete-cuadros-y-unas-cumbias-la-compania-migrante-que-pone-en-escena-a-garcia-lorca-en-mexico.html",rel:[m,n,o],target:p},children:[{type:a,value:" obras de teatro populares"}]},{type:a,value:" en los barrios, torneos de fútbol y baloncesto en las calles, memoria histórica que cure las heridas de la violencia; diálogos, acuerdos, trabajar en conjunto para construir la paz sin que nadie la imponga; que el arte cuente las historias de la gente común, que humanice, que cambie la narrativa; árboles, jardines y fuentes; "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Famerica-futura\u002F2023-04-02\u002Flas-mexicanas-que-levantan-un-muro-de-manglares-para-proteger-la-costa-ante-los-huracanes.html",rel:[m,n,o],target:p},children:[{type:a,value:"abrazar el mar"}]},{type:a,value:", fundirse con la naturaleza para sobrevivir."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Seis mexicanos —una abogada ambientalista reconvertida en centinela del mar, un periodista de derechos humanos, una académica especializada en violencia, un curador de arte, una experta en políticas públicas y un biólogo marino— esbozan desde su experiencia los pasos para construir la ciudad ideal del futuro en México. Todo, a partir de ideas prácticas que se han hecho, se están haciendo, se pueden hacer. Todos tienen en común que son invitados del"},{type:b,tag:e,props:{href:"https:\u002F\u002Fforomdc.org\u002F",rel:[m,n,o],target:p},children:[{type:a,value:" foro empresarial Mar de Cortés"}]},{type:a,value:", celebrado estos días en Cabo San Lucas, Baja California Sur, con el foco puesto, precisamente, en construir el futuro de las ciudades."}]},{type:a,value:c},{type:b,tag:g,props:{id:q},children:[{type:b,tag:e,props:{href:"#espantap%C3%A1jaros-marinos",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:r}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"María Ugarte Luiselli (51 años) pasó muchas jornadas en el Mar de Cortés. Como nadie detenía a los pesqueros furtivos que diezmaban sus aguas, decidió volverse una suerte de espantapájaros marino y vigilarlos ella misma. Hace 15 años creó la"},{type:b,tag:e,props:{href:"https:\u002F\u002Froclapaz.org\u002F",rel:[m,n,o],target:p},children:[{type:a,value:" Red de Observadores Ciudadanos – La Paz Waterkeeper"}]},{type:a,value:" “para proteger la bahía de La Paz de cualquier amenaza contra el patrimonio natural”. Al principio, la gente le decía que no tenía competencia ni autoridad. “Precisamente porque la autoridad no lo está haciendo”, respondía. Muchos años después, ha logrado la incautación de toneladas de pesca ilegal y que los furtivos abandonaran la zona “por disuasión, nadie quiere hacer algo ilegal enfrente de nadie: estar en el mar, simplemente la presencia, inhibía el delito”. Ahora La Red guía a los policías: “Se suben en la panga con nosotros y los llevamos, armamos el operativo, hacemos la labor de inteligencia antes y les decimos: ‘Va a pasar esto, esto y esto’, y ellos actúan”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para Ugarte Luiselli, que nació en Ciudad de México pero se hizo sudcaliforniana en 2001, su ciudad ideal radica en la gente: en una ciudadanía que se implique en los problemas de su comunidad y, como hizo ella y todos los que le siguieron, luchen por cambiarla. La suya es una historia de éxito y participación ciudadana. “Creo en el logro de lo imposible, lo viví y estoy aquí para demostrar que una idea que pareciera ridícula es alcanzable. Mi ciudad ideal es en la que los ciudadanos que la habitan realmente se la apropian, trabajan para preservarla y vivirla. Los ciudadanos somos clave como agentes de cambio”. Su experiencia no quedó en La Paz: el modelo de vigilancia ciudadana de los mares que diseñaron se ha replicado en Cozumel, Iztapa o la Reserva de la Biosfera Marismas Nacionales de Nayarit."}]},{type:a,value:c},{type:b,tag:g,props:{id:s},children:[{type:b,tag:e,props:{href:"#memoria-hist%C3%B3rica-f%C3%BAtbol-y-teatro",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:t}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Cuando Marcos Vizcarra (36 años) era niño, en Culiacán era habitual ver a jóvenes en las calles que jugaban torneos de fútbol y baloncesto. “Ya no existen”, lamenta. El periodista sinaloense, especializado en la cobertura de derechos humanos, cree que la violencia en su ciudad natal, asolada estos días por la guerra interna del Cártel de Sinaloa, ha matado también iniciativas tan populares y sencillas como el deporte. “Tampoco hay obras de teatro en las colonias, tienes que irte hasta el centro. Normalmente, son obras que cuestan y el poder adquisitivo de Sinaloa es muy bajo”. Ni programas artísticos ni culturales. Su ciudad ideal retomaría todo eso en los barrios. “Culiacán no es de los ciudadanos, es una realidad: cohabitamos con criminales que se han apoderado del territorio. Necesitamos recuperar la ciudad”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La violencia ha dejado una huella profunda en Culiacán. Para sobrevivirla, Vizcarra apuesta por la memoria histórica. “Ver primero hacia las víctimas, rascar el pasado, que los ciudadanos y ciudadanas entendamos todo ese dolor y lo hagamos propio, lo reconozcamos, lo abracemos y lo reparemos en conjunto”. Todo pasa, cree, por reforzar las instituciones de seguridad y las judiciales, el Estado de derecho, “pero no desde el ámbito punitivo, sino de la construcción de eso que le llaman el tejido social a través del fortalecimiento de las comunidades. "},{type:b,tag:C,props:{},children:[{type:a,value:"Pa’"}]},{type:a,value:" no sonar tan técnico: ir hacia esas colonias que se encuentran con problemáticas enormes porque no tienen acceso suficiente a la educación, porque no hay calles pavimentadas, y llevar servicios públicos que generen oportunidades de desarrollo”."}]},{type:a,value:c},{type:b,tag:g,props:{id:u},children:[{type:b,tag:e,props:{href:"#construir-la-paz-en-colectivo-no-imponerla",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De la boca de Iliana Padilla Reyes (43 años) salen en varias ocasiones las ideas “acuerdo”, “diálogo” y “conjunto”. Para la doctora en estudios regionales, experta en seguridad, y autora del libro "},{type:b,tag:C,props:{},children:[{type:a,value:"Geografía de la violencia en Culiacán"}]},{type:a,value:" (2017), la ciudad ideal pasa por tener “instituciones sólidas” que “construyan la paz, no la impongan”. En su discurso, las instituciones son la fuerza conjunta de un Estado con mecanismos eficaces y una ciudadanía comprometida. “Una ciudad ideal, sin duda, sería una ciudad con justicia social”, razona. ¿Para lograrlo? “Un diagnóstico franco para identificar qué es aquello que podemos trabajar y generar acuerdos para trabajarlos en conjunto”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Reside en Querétaro, pero nació en Culiacán, donde participa en un proyecto de Conacyt (Consejo Nacional de Humanidades, Ciencias y Tecnologías) que une a académicos, colectivos de búsqueda de desaparecidos, artistas, periodistas, grupos anticorrupción… “Hemos integrado una red de discusión que se reúne cada tanto tiempo en diferentes espacios. Los que nunca participan son los empresarios, están en otro nivel, u organizan este tipo de foros donde también son muy selectivos. Creo que mientras tengamos esas divisiones en la discusión, en la reflexión, no vamos a poder llegar a acuerdos colectivos”."}]},{type:a,value:c},{type:b,tag:g,props:{id:w},children:[{type:b,tag:e,props:{href:"#humanizar-y-cambiar-la-narrativa-desde-el-arte",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:x}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En 2017, el curador de arte Pedro Alonzo (53 años) hizo un proyecto con el artista francés JR en Tecate: "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Felpais\u002F2017\u002F09\u002F26\u002Feps\u002F1506377118_150637.html",rel:[m,n,o],target:p},children:[{type:a,value:"un niño gigante que se elevaba sobre la frontera y miraba hacia Estados Unidos"}]},{type:a,value:". “JR y yo estábamos en un restaurante en San Diego escuchando a [Donald] Trump denigrar a los inmigrantes, nos miramos y dijimos: ‘Oye, él está haciendo esta obra más importante de la que nos habíamos imaginado’. Es muy fácil utilizar cifras para deshumanizar, pero cuando pones la imagen de un niño inocente, humanizas… Eso es muy importante, crear historias de gente, cambiar la narrativa, es muy difícil que estén criticando a México si nos conocen”."}]},{type:a,value:c},{type:b,tag:g,props:{id:y},children:[{type:b,tag:e,props:{href:"#%C3%A1rboles-parques-e-impuestos",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Liliana Alvarado no pide mucho. Se conforma con lo fundamental, sin grandes lujos: en su ciudad ideal hay buenos servicios públicos, árboles, parques, fuentes y seguridad. Pero la directora general de Ethos, un think tank enfocado en las políticas públicas, vive en Ciudad de México, una ciudad-monstruo en la que en muchos barrios no hay ni esas cosas tan básicas. “En México los servicios públicos dejan mucho que desear en términos de educación, salud, acceso a ciertos servicios como incluso el agua. En mi ciudad ideal estaríamos rodeados de zonas verdes, pero, más importante, creo que en México necesitamos ciudades que sean seguras. No es algo muy sofisticado, pero como en muchas ciudades no tenemos ni lo basiquito, mi ciudad del futuro no parece muy del futuro”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Una ciudad ideal necesita desarrollo sostenible y financiación, que son los campos en los que se ha centrado Alvarado en su carrera. Una de sus grandes ideas de recaudación, la que ha venido a exponer al foro, es la subida del impuesto predial, una medida factible y realista, defiende, que afecta a todos los propietarios de tierras, pero costará más a los grandes terratenientes por pura proporción. “Desafortunadamente en México son pocos los municipios que recaudan sus ingresos de manera apropiada para invertir en el desarrollo sostenible de las ciudades. La recaudación por impuesto predial es baja. Hay un área de oportunidad, la mayor parte de los municipios en el país tienen espacio para crecer esa recaudación. Desafortunadamente, hay poca voluntad política: implica un aumento de impuestos y eso en términos electorales resta votos”."}]},{type:a,value:c},{type:b,tag:g,props:{id:A},children:[{type:b,tag:e,props:{href:"#una-ciudad-abrazada-por-el-mar",ariaHidden:h,tabIndex:i},children:[{type:b,tag:j,props:{className:[k,l]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La ciudad ideal de Octavio Aburto Oropeza (51 años) tiene mucho que ver con aquello a lo que ha dedicado su vida: el mar. Biólogo marino, nació tierra adentro, en Ciudad de México, pero a los 17 años se trasladó a La Paz, donde vivió 15 años. Desde hace unos años es profesor en el Instituto Scripps de Oceanografía de San Diego. “Una ciudad que respeta la conexión entre la costa y el mar, que respeta sus manglares, sus esteros, que sus construcciones tratan de imitar la diversidad de ecosistemas y de especies que se entrelazan entre mar y tierra”. “Los ecosistemas se subsidian”, explica. Por ejemplo: el mar produce peces que alimentan a las aves marinas, que llegan a tierra y con su guano fertilizan los cactus de Baja California Sur, que “generan toda la vida del desierto”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ese principio, pero aplicado a las ciudades: “Conectar todo para hacernos más resilientes al cambio climático”. Aburto Oropeza lo haría a partir de “cinco ramas”. La primera: “Tecnología y economías azules, innovar: en lugar de hacer espigones de concreto en la costa, plantar manglares, soluciones utilizando la naturaleza”. La segunda: dar menos importancia a actividades extractivas como la pesca, “que no dejan tanto dinero como pensamos” y dar más peso a otras no extractivas como buceo, avistamiento de ballenas, o surf. La tercera: reivindicar identidad. “Muchas ciudades han perdido identidad relacionada con la cultura que vivía ahí. En el Golfo de California hemos perdido el 50% de las culturas históricas”. La cuarta: educar desde la infancia. La quinta: “Invertir en que los jóvenes busquen colectivamente imaginar sus ciudades en el futuro”."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fasi_seria_mi_ciudad_ideal_en_el_mexico_del_futuro",extension:".md",createdAt:D,updatedAt:D}}],fetch:{},mutations:[]}}("text","element","\n","p","a",3,"h3","true",-1,"span","icon","icon-link","nofollow","noopener","noreferrer","_blank","espantapájaros-marinos","Espantapájaros marinos","memoria-histórica-fútbol-y-teatro","Memoria histórica, fútbol y teatro","construir-la-paz-en-colectivo-no-imponerla","Construir la paz en colectivo, no imponerla","humanizar-y-cambiar-la-narrativa-desde-el-arte","Humanizar y cambiar la narrativa desde el arte","árboles-parques-e-impuestos","Árboles, parques e impuestos","una-ciudad-abrazada-por-el-mar","Una ciudad abrazada por el mar","em","2025-04-23T06:21:15.378Z")));